files.content:
html {
  height: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 360px;
  min-height: 100%;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

.form {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-sizing: border-box;
  max-width: 660px;
  min-height: 180px;
  margin: 0;
  border: 2px solid #000;
  padding: 20px;
  background-color: #feafe8;
}

.form-wrapper {
  display: flex;
  width: 100%;
}

.title {
  margin: 0 0 10px;
  font-family: inherit;
  font-weight: 600;
  font-size: 20px;
  text-transform: uppercase;
}

button {
  width: 100%;
  border: 2px solid #000;
  padding: 10px 40px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

input,
label {
  display: block;
}

.label {
  margin-top: 0;
  margin-bottom: 6px;
}

input {
  width: 100%;
  border: 2px solid #000;
  padding: 10px 12px;
  font-family: inherit;
  font-size: inherit;
  background-color: #fff;
}

input::placeholder {
  color: rgb(0 0 0 / 0.6);
}

input:invalid {
  background-color: #fd24af;
}

input:invalid::placeholder {
  color: #000;
}

input:disabled {
  border-color: rgb(0 0 0 / 0.6);
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
}

button:focus {
  outline: none;
}

input:focus {
  outline: none;
}

button:focus-visible {
  outline: 5px solid #fd24af;
}

input:focus-visible {
  outline: 5px solid #fd24af;
}
